// =============================================================================
// Backfill planning — which company-months the 1st-of-month cron generates
// =============================================================================
// Owner decision ("keep and alert"): backfill fills GAPS only. A company-month
// that already has a report is never regenerated by backfill — before this,
// every run re-uploaded every past CSV (upsert: true) and bumped
// generation_number, silently rewriting invoiced months whenever upstream
// summaries had drifted. Drift on existing months is now surfaced by
// reconcile_billing_months (locked_alerts) instead of being written over.
//
//   1. planBackfill       — has_report = false AND the month has passed
//   2. partitionByLock    — drop locked months; a failed lock check is an error
//   3. runBackfillReconcile — reconcile_billing_months over the planned months
//                            before generating; failure alerts and continues
// =============================================================================

import type { RaiseBillingAlertFn, RpcClient, RpcResponse } from '../../_shared/billingAlerts.ts';
import { checkMonthLock, monthKey, monthStartDate } from './monthLock.ts';
import type { IsMonthLockedFn } from './monthLock.ts';

/** The v_eom_report_availability columns backfill selects. */
export interface AvailabilityRow {
  company_id: string;
  company_name: string;
  report_year: number;
  report_month: number;
  has_report: boolean;
}

export interface BackfillPlan {
  candidates: AvailabilityRow[];
  alreadyReported: number;
  notYetPast: number;
}

export function planBackfill(
  rows: AvailabilityRow[],
  isPastMonth: (year: number, month: number) => boolean,
): BackfillPlan {
  const candidates: AvailabilityRow[] = [];
  let alreadyReported = 0;
  let notYetPast = 0;

  for (const row of rows) {
    if (typeof row.has_report !== 'boolean') {
      // A missing has_report would otherwise read as "no report" and regenerate it.
      throw new Error(
        `v_eom_report_availability row ${row.company_id}:${monthKey(row.report_year, row.report_month)} ` +
          `has non-boolean has_report ${JSON.stringify(row.has_report)}`,
      );
    }
    if (!isPastMonth(row.report_year, row.report_month)) {
      notYetPast++;
    } else if (row.has_report) {
      alreadyReported++;
    } else {
      candidates.push(row);
    }
  }

  return { candidates, alreadyReported, notYetPast };
}

export interface LockPartition {
  toGenerate: AvailabilityRow[];
  locked: AvailabilityRow[];
  lockErrors: Array<{ row: AvailabilityRow; message: string }>;
}

export async function partitionByLock(
  candidates: AvailabilityRow[],
  isLocked: IsMonthLockedFn,
): Promise<LockPartition> {
  const partition: LockPartition = { toGenerate: [], locked: [], lockErrors: [] };
  for (const row of candidates) {
    const state = await checkMonthLock(isLocked, {
      companyId: row.company_id,
      year: row.report_year,
      month: row.report_month,
    });
    if (state.kind === 'open') partition.toGenerate.push(row);
    else if (state.kind === 'locked') partition.locked.push(row);
    else partition.lockErrors.push({ row, message: state.message });
  }
  return partition;
}

// =============================================================================
// reconcile_billing_months
// =============================================================================

/** Inclusive first-of-month bounds covering every given company-month. */
export function reconcileRangeFor(
  rows: Array<{ report_year: number; report_month: number }>,
): { from: string; to: string } | null {
  if (rows.length === 0) return null;
  // 'YYYY-MM-01' strings sort chronologically.
  const months = rows.map((r) => monthStartDate(r.report_year, r.report_month)).sort();
  return { from: months[0], to: months[months.length - 1] };
}

export type ReconcileFn = (from: string, to: string) => Promise<RpcResponse<unknown>>;

/** Binds `reconcile_billing_months(p_from, p_to, p_dry_run => false)`. */
export function makeReconcileBillingMonths(client: RpcClient): ReconcileFn {
  return async (from, to) =>
    await client.rpc('reconcile_billing_months', { p_from: from, p_to: to, p_dry_run: false });
}

export const EOM_RECONCILE_FAILED_ALERT = 'eom_reconcile_failed';

export type BackfillReconcileResult =
  | { action: 'reconcile_skipped'; reason: 'no_months_to_generate' }
  | { action: 'reconcile_ok'; from: string; to: string; summary: Record<string, unknown> }
  | {
    action: 'reconcile_failed';
    from: string;
    to: string;
    error: string;
    summary: Record<string, unknown> | null;
    alert_raised: boolean;
    alert_error: string | null;
  };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Runs reconciliation for the months backfill is about to generate. Never
 * throws and never blocks generation: a failure raises eom_reconcile_failed
 * and is returned for the response body. Any status other than 'ok' — an RPC
 * error, a thrown call, an unexpected payload, or status 'failed' — is a failure.
 */
export async function runBackfillReconcile(
  range: { from: string; to: string } | null,
  reconcile: ReconcileFn,
  raise: RaiseBillingAlertFn,
): Promise<BackfillReconcileResult> {
  if (!range) return { action: 'reconcile_skipped', reason: 'no_months_to_generate' };

  let error: string | null = null;
  let summary: Record<string, unknown> | null = null;

  try {
    const response = await reconcile(range.from, range.to);
    if (response.error) {
      error = `reconcile_billing_months RPC error: ${response.error.message}`;
    } else if (!isRecord(response.data)) {
      error = `reconcile_billing_months returned unexpected payload: ${JSON.stringify(response.data)}`;
    } else {
      summary = response.data;
      if (summary.status !== 'ok') {
        error = `reconcile_billing_months returned status ${JSON.stringify(summary.status)}`;
      }
    }
  } catch (err) {
    error = `reconcile_billing_months threw: ${err instanceof Error ? err.message : String(err)}`;
  }

  if (error === null && summary) {
    return { action: 'reconcile_ok', from: range.from, to: range.to, summary };
  }

  const failure = error ?? 'reconcile_billing_months failed';
  const alert = await raise({
    type: EOM_RECONCILE_FAILED_ALERT,
    entityId: `${range.from.slice(0, 7)}..${range.to.slice(0, 7)}`,
    title:
      `Billing reconciliation FAILED before end-of-month report backfill ` +
      `(${range.from.slice(0, 7)} to ${range.to.slice(0, 7)}) — reports were still generated ` +
      `from the summaries as they stand: ${failure}`,
    metadata: { p_from: range.from, p_to: range.to, error_message: failure, reconcile_summary: summary },
    severity: 'error',
  });

  return {
    action: 'reconcile_failed',
    from: range.from,
    to: range.to,
    error: failure,
    summary,
    alert_raised: alert.ok,
    alert_error: alert.ok ? null : alert.error,
  };
}
